import type { TicketFilter } from './platform';

// ---- Invitation codes ----
export type InvitationCodeStatus = 'active' | 'expired' | 'revoked';
export type InvitationCodeFilter = 'all' | InvitationCodeStatus;

export interface InvitationCode {
  id: string;
  /** What people type on the "Join with an invitation code" screen, e.g. ATLA-2026 (generated by the server). */
  code: string;
  /** Admin's own note, e.g. "Autumn intake". */
  label: string;
  createdAt: string;
  expiresAt: string;
  /** null = unlimited. */
  maxUses: number | null;
  uses: number;
  status: InvitationCodeStatus;
}

export interface InvitationCodesQuery { status?: InvitationCodeFilter; q?: string; page?: number; pageSize?: number }
export interface InvitationCodesPage { items: InvitationCode[]; total: number; counts: Record<InvitationCodeFilter, number> }

export interface NewInvitationCode {
  label?: string;
  /** Days until the code stops working. */
  expiresInDays: number;
  /** null = unlimited. */
  maxUses: number | null;
}

// ---- Renewal requests ----
export type RenewalStatus = 'pending' | 'approved' | 'declined';
export type RenewalTerm = 6 | 12 | 24;

export interface RenewalRequest {
  id: string;
  /** e.g. REN-0007 */
  reference: string;
  termMonths: RenewalTerm;
  note?: string;
  submittedAt: string;
  status: RenewalStatus;
  decidedAt?: string;
  /** Message from the platform administrator, if any. */
  decisionMessage?: string;
}

export interface RenewalOverview {
  /** ISO date the organisation's current access ends; null until the platform team has set it. */
  accessEndsAt: string | null;
  requests: RenewalRequest[];
}

export interface NewRenewalRequest { termMonths: RenewalTerm; note?: string }

// ---- Support tickets (organisation side) ----
export interface NewTicket { subject: string; priority: 'high' | 'normal' | 'low'; message: string }
export type OrganisationTicketFilter = TicketFilter;
